CREATE TABLE itens_pedido (
  pedido_id INT, produto_id INT,
  qtd INT, preco_unitario DECIMAL(10,2)
);

SELECT p.nome, i.qtd, i.preco_unitario, (i.qtd * i.preco_unitario) AS subtotal 
FROM itens_pedido i 
JOIN produtos p ON i.produto_id = p.id;

